#include "main.h"
#include <string.h>
extern UART_HandleTypeDef {{uart_handle}};

int main(void) {
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_USART2_UART_Init();
  const char* msg = "{{message}}\r\n";
  while (1) {
    HAL_UART_Transmit(&{{uart_handle}}, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);
    HAL_Delay(1000);
  }
}
